async () => {
  const { exec } = require('child_process');
  const util = require('util');
  const execPromise = util.promisify(exec);

  try {
    // Make the script executable
    await execPromise('chmod +x /tmp/mcp-workspace/network_monitor.sh');

    // Start the script in the background
    await execPromise('nohup /tmp/mcp-workspace/network_monitor.sh > /dev/null 2>&1 &');

    return 'Script made executable and started in background';
  } catch (error) {
    return `Error: ${error.message}`;
  }
}

() => {
  const fs = require('fs');
  const path = '/tmp/mcp-workspace/network_monitor.sh';

  // Read the current permissions
  const stats = fs.statSync(path);
  const currentMode = stats.mode;

  // Add execute permissions (owner, group, others)
  const newMode = currentMode | fs.constants.S_IXUSR | fs.constants.S_IXGRP | fs.constants.S_IXOTH;

  // Apply new permissions
  fs.chmodSync(path, newMode);

  return 'Script made executable';
}

